<?=h($currency)?> 0.00</b></div><div><span>Tax</span><b id="tax"><?=h($currency)?> 0.00</b></div><div class="total-line"><span>Total</span><b id="total"><?=h($currency)?> 0.00</b></div></div></div><div class="form-actions"><a class="button light" href="/invoices">Cancel</a><button class="button primary">Create <?=h($type)?></button></div></form></div>
<?php elseif($page==='view'): $q=$db->prepare('SELECT d.*,c.name customer,c.email,c.phone,c.address FROM documents d LEFT JOIN customers c ON c.id=d.customer_id WHERE d.id=?');$q->execute([(int)($_GET['id']??0)]);$doc=$q->fetch(); if(!$doc): ?><div class="panel empty">Document not found.</div><?php else: $q=$db->prepare('SELECT * FROM document_items WHERE document_id=?');$q->execute([$doc['id']]);$items=$q->fetchAll(); ?><div class="document-toolbar"><a class="button light" href="/invoices">← Back to documents</a><div class="inline-actions"><?php if($doc['type']==='quote'): ?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="convert"><input type="hidden" name="id" value="<?=$doc['id']?>"><button class="button primary">Convert to invoice</button></form><?php elseif($doc['status']!=='paid'): ?><form method="post" class="payment-form"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="payment"><input type="hidden" name="id" value="<?=$doc['id']?>"><input name="amount" type="number" min="0.01" step="0.01" max="<?=h($doc['total']-$doc['paid'])?>" placeholder="Payment amount" required><button class="button primary">Record payment</button></form><?php endif ?><button class="button light" onclick="window.print()">↓ Print / Save PDF</button></div></div><div class="invoice-paper"><div class="paper-top"><div><div class="paper-brand"><img class="brand-icon" src="/assets/ledger-emblem-transparent.png" alt=""> Ledger</div><p>Professional invoicing for your business</p></div><div class="paper-type"><h2><?=strtoupper(h($doc['type']))?></h2><b><?=h($doc['number'])?></b></div></div><div class="paper-parties"><div><small>BILL TO</small><h3><?=h($doc['customer']??'Customer')?></h3><p><?=h($doc['email']??'')?><?= $doc['phone']?' · '.h($doc['phone']):'' ?><br><?=nl2br(h($doc['address']??''))?></p></div><div><div><small>ISSUE DATE</small><b><?=date('M j, Y',strtotime($doc['issue_date']))?></b></div><div><small>DUE DATE</small><b><?=$doc['due_date']?date('M j, Y',strtotime($doc['due_date'])):'—'?></b></div><div><small>STATUS</small><span class="badge <?=h($doc['status'])?>"><?=h(ucfirst($doc['status']))?></span></div></div></div><table class="paper-table"><thead><tr><th>DESCRIPTION</th><th>QTY</th><th>UNIT PRICE</th><th>AMOUNT</th></tr></thead><tbody><?php foreach($items as $it): ?><tr><td><?=h($it['description'])?></td><td><?=number_format((float)$it['quantity'],2)?></td><td><?=money($it['unit_price'],$doc['currency'])?></td><td><?=money($it['line_total'],$doc['currency'])?></td></tr><?php endforeach ?></tbody></table><div class="paper-summary"><div><span>Subtotal</span><b><?=money($doc['subtotal'],$doc['currency'])?></b></div><div><span>Tax (<?=number_format((float)$doc['tax_rate'],2)?>%)</span><b><?=money($doc['tax_amount'],$doc['currency'])?></b></div><div class="total-line"><span>Total</span><b><?=money($doc['total'],$doc['currency'])?></b></div><?php if($doc['paid']>0): ?><div><span>Paid</span><b><?=money($doc['paid'],$doc['currency'])?></b></div><div><span>Balance due</span><b><?=money($doc['total']-$doc['paid'],$doc['currency'])?></b></div><?php endif ?></div><?php if($doc['notes']): ?><div class="paper-notes"><small>NOTES</small><p><?=nl2br(h($doc['notes']))?></p></div><?php endif ?><div class="paper-footer">Thank you for your business.</div></div><?php endif ?>
<?php else: ?><div class="panel form-panel"><h3>Business settings</h3><p>Your documents are currently issued in <?=h($currency)?>. Change <code>APP_CURRENCY</code> in docker-compose.yml to use another currency.</p><p>Business identity customization and team access can be added next.</p></div><?php endif ?><footer class="footer">Made for the people building their business. &nbsp;·&nbsp; Ledger</footer></main>
<script>function addLine(){const b=document.querySelector('#items');const r=b.rows[0].cloneNode(true);r.querySelectorAll('input').forEach(i=>{if(i.name==='description[]')i.value='';else if(i.name==='quantity[]')i.value='1';else i.value='0'});b.appendChild(r)}function removeLine(btn){const b=document.querySelector('#items');if(b.rows.length>1)btn.closest('tr').remove();else btn.closest('tr').querySelectorAll('input').forEach(i=>i.value=i.name==='quantity[]'?'1':i.name==='price[]'?'0':'');calc()}function calc(){let s=0;document.querySelectorAll('#items tr').forEach(r=>{const q=parseFloat(r.querySelector('[name="quantity[]"]').value)||0,p=parseFloat(r.querySelector('[name="price[]"]').value)||0,t=q*p;s+=t;r.querySelector('.line-total').textContent=t.toFixed(2)});const tax=s*(parseFloat(document.querySelector('[name="tax_rate"]')?.value)||0)/100;const c=<?=json_encode($currency)?>;document.querySelector('#subtotal').textContent=c+' '+s.toFixed(2);document.querySelector('#tax').textContent=c+' '+tax.toFixed(2);document.querySelector('#total').textContent=c+' '+(s+tax).toFixed(2)}calc();</script></body></html>
